/**
 * scripts/rls-enforcement/check-enforcement-drift.ts
 *
 * Round 58 Phase 1+ — drift ratchet for the generator-driven RLS+GRANT
 * compiler. Regenerates the migration + blockers report into memory and
 * fails (non-zero exit) if the regenerated bytes differ from what is
 * currently committed at:
 *   db/migrations/20260910_rls_enforcement_expansion_round58.sql
 *   reports/union-eyes-rls-enforcement-blockers.json
 *
 * This proves the committed migration is not hand-edited/stale relative to
 * the manifest (db/rls-storage-authority) and geometry
 * (reports/union-eyes-rls-geometry.json) it was generated from — the same
 * "generate to a temp buffer, diff byte-for-byte" pattern this repo already
 * uses elsewhere for generated-artifact drift checks.
 *
 * Regenerating geometry itself (derive-table-geometry.ts) is NOT part of
 * this drift check — geometry is derived from the schema source of truth
 * and is checked in separately; re-deriving it here would make an ordinary
 * schema edit look like "drift" in the wrong artifact.
 */
import { execFileSync } from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";

const REPO_ROOT = path.resolve(__dirname, "../..");
const MIGRATION_PATH = path.join(REPO_ROOT, "db/migrations/20260910_rls_enforcement_expansion_round58.sql");
const BLOCKERS_PATH = path.join(REPO_ROOT, "reports/union-eyes-rls-enforcement-blockers.json");

function main() {
  const committedMigration = fs.readFileSync(MIGRATION_PATH, "utf8");
  const committedBlockers = fs.readFileSync(BLOCKERS_PATH, "utf8");

  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "rls-drift-"));
  const tmpMigration = path.join(tmpDir, "generated.sql");
  const tmpBlockers = path.join(tmpDir, "generated-blockers.json");

  execFileSync(
    "npx",
    ["tsx", path.join(__dirname, "generate-rls-enforcement-migration.ts")],
    {
      cwd: REPO_ROOT,
      stdio: "inherit",
      env: {
        ...process.env,
        RLS_ENFORCEMENT_OUT_MIGRATION: tmpMigration,
        RLS_ENFORCEMENT_OUT_BLOCKERS: tmpBlockers,
      },
    }
  );

  const regeneratedMigration = fs.readFileSync(tmpMigration, "utf8");
  const regeneratedBlockers = fs.readFileSync(tmpBlockers, "utf8");
  fs.rmSync(tmpDir, { recursive: true, force: true });

  let drift = false;
  if (regeneratedMigration !== committedMigration) {
    console.error(
      "DRIFT: regenerating db/migrations/20260910_rls_enforcement_expansion_round58.sql produces different bytes than what is committed."
    );
    drift = true;
  }
  // Blockers report includes a `generatedAt` timestamp that legitimately
  // differs on every run — compare only the `blockers` array content.
  const committedBlockersJson = JSON.parse(committedBlockers);
  const regeneratedBlockersJson = JSON.parse(regeneratedBlockers);
  if (JSON.stringify(regeneratedBlockersJson.blockers) !== JSON.stringify(committedBlockersJson.blockers)) {
    console.error(
      "DRIFT: regenerating reports/union-eyes-rls-enforcement-blockers.json produces a different blockers list than what is committed."
    );
    drift = true;
  }

  if (drift) {
    console.error("Run `pnpm --filter @nzila/union-eyes rls:generate-enforcement` and commit the result.");
    process.exit(1);
  }

  console.log("No drift: committed RLS enforcement migration + blockers report match the generator output.");
}

main();
